import React, { useEffect, useMemo, useRef, useState } from 'react';
import { useIntl } from 'react-intl';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
import { ChevronLeftIcon, ChevronRightIcon } from '../../../icons';

type ColourVariant = {
  /** SFCC variation value (e.g. 'lilac', 'raspberry') */
  value: string;
  /** Display name for label and aria-label (e.g. 'Lilac', 'Raspberry') */
  name: string;
  /**
   * Resolved URL of the swatch-viewType product image for this colour.
   * When absent the colour is not surfaced to the shopper at all — no swatch renders (AC5).
   */
  imageUrl?: string;
  /**
   * Whether this colour is orderable. SDK's VariationAttributeValue.orderable is
   * `boolean | undefined` — treat undefined as true (orderable) when mapping.
   * A non-orderable colour is not surfaced to the shopper at all — no swatch renders (AC5).
   */
  orderable: boolean;
};

/** A colour that passed the AC5 gate: guaranteed to carry a resolved swatch image. */
type OfferedColourVariant = ColourVariant & { imageUrl: string };

/** Figma: pagination appears if there are more than 4 swatches. */
const PAGE_SIZE = 4;

/**
 * Swatch images render into a 47px-wide box, so request a DIS-scaled image rather than the
 * full-resolution product shot (AGENTS.md > Performance > Images: "Never render
 * full-resolution images at thumbnail size"). 96px covers the 47px box at 2x DPR; q=60
 * matches the quality the base retail app's image-gallery already requests.
 */
const SWATCH_IMAGE_WIDTH = 96;
/** 96px at the 2/3 aspect ratio the swatch box uses — keeps the intrinsic ratio honest. */
const SWATCH_IMAGE_HEIGHT = 144;
const SWATCH_IMAGE_QUALITY = 60;

const ZIMM_COLOUR_SWATCHES_RECIPE = 'ZimmColourSwatches';

/**
 * Appends SFCC Dynamic Image Service sizing params to a resolved swatch URL. Equivalent to
 * the `[?sw={width}&q=60]` bracket notation the base app feeds to DynamicImage, but for a
 * fixed-size swatch there is only one width to serve, so DynamicImage's responsive
 * srcSet/sizes machinery would be dead weight. Picks the separator defensively — `link`
 * (the fallback when `disBaseLink` is absent) can already carry a query string.
 */
const sizedSwatchUrl = (url: string) => {
  if (url.startsWith('data:')) return url;
  return `${url}${url.includes('?') ? '&' : '?'}sw=${SWATCH_IMAGE_WIDTH}&q=${SWATCH_IMAGE_QUALITY}`;
};

type ColourSwatchesProps = {
  /** All available colour variants for this product */
  variants: readonly ColourVariant[];
  /** Currently selected colour value — omit or pass undefined if none selected */
  selectedValue?: string;
  /** Called when the shopper clicks or keyboard-selects a swatch */
  onSelect: (value: string) => void;
};

/**
 * Renders a radiogroup of colour swatches for the PDP. Pure UI — receives fully
 * resolved props from the parent page; does not call any SDK hooks.
 */
const ColourSwatches = ({ variants, selectedValue, onSelect }: ColourSwatchesProps) => {
  const intl = useIntl();
  const styles = useMultiStyleConfig(ZIMM_COLOUR_SWATCHES_RECIPE, {});
  const swatchRefs = useRef<(HTMLButtonElement | null)[]>([]);
  // pendingFocusIndexRef: position within the page to focus after a page change triggered
  // by keyboard navigation. Set in handleKeyDown, consumed in the page useEffect.
  const pendingFocusIndexRef = useRef<number | null>(null);
  const [page, setPage] = useState(0);

  // AC5: a colour is only offered if it has a resolved swatch image AND is orderable.
  // An unavailable/disabled colour is withheld entirely rather than shown in a disabled
  // state — confirmed by the BA 2026-08-21, superseding the earlier `opacity: 0.4` reading.
  // Memoised to avoid repeated filter passes on every render and to keep pageCount stable
  // across renders where variants hasn't changed.
  // Type predicate so `imageUrl` narrows to `string` in the render below — Array.filter
  // alone would leave it `string | undefined` and force an assertion at the img src.
  const swatchVariants = useMemo(
    () => variants.filter((v): v is OfferedColourVariant => Boolean(v.imageUrl) && v.orderable),
    [variants],
  );
  // Always-current ref so the auto-advance effect can read swatchVariants without depending
  // on it — if it depended on swatchVariants, any parent re-render that creates a new
  // variants array identity would reset a chevron-navigated page back to the selected
  // colour's page. The ref is updated synchronously during render, before effects run.
  const swatchVariantsRef = useRef(swatchVariants);
  swatchVariantsRef.current = swatchVariants;
  // AC1: single colour → text label only, no swatch row.
  const showSwatches = swatchVariants.length > 1;

  const pageCount = Math.ceil(swatchVariants.length / PAGE_SIZE);
  const showPagination = swatchVariants.length > PAGE_SIZE;
  const pagedVariants = swatchVariants.slice(page * PAGE_SIZE, (page + 1) * PAGE_SIZE);

  // Resolve from swatchVariants (not variants) so a withheld colour's name is never shown
  // in the label — AC5 requires withheld colours not to be surfaced at all.
  const selectedName = swatchVariants.find((v) => v.value === selectedValue)?.name;
  // AC1: when there is exactly one offered colour, show its name even before a selection
  // is made. Keyed off swatchVariants, not variants — a product whose other colours were
  // all withheld is a single-colour product as far as the shopper can tell.
  const labelName = selectedName ?? (swatchVariants.length === 1 ? swatchVariants[0]?.name : undefined);

  // Stable primitive derived from the offered set's content (not identity). Changes when a
  // colour gains/loses its image or orderable status; stays the same when a parent re-render
  // produces a new variants array reference with the same logical values.
  const swatchVariantsKey = JSON.stringify(swatchVariants.map((v) => v.value));

  // When the selected colour is on a different page (e.g. deep link with ?color=), advance
  // to that page automatically so the selected swatch is always visible.
  // Deps: selectedValue + swatchVariantsKey — the key re-fires when the offered set changes
  // content so page is recalculated; swatchVariants is still read via ref so identity-only
  // parent re-renders do not reset a chevron-navigated page.
  useEffect(() => {
    if (selectedValue === undefined) return;
    const globalIndex = swatchVariantsRef.current.findIndex((v) => v.value === selectedValue);
    if (globalIndex === -1) return;
    setPage(Math.floor(globalIndex / PAGE_SIZE));
  }, [selectedValue, swatchVariantsKey]);

  // Clamp page to a valid range when swatchVariants shrinks (e.g. variants prop changes).
  useEffect(() => {
    setPage((p) => Math.min(p, Math.max(0, pageCount - 1)));
  }, [pageCount]);

  // After a page change triggered by keyboard navigation, focus the pending swatch.
  useEffect(() => {
    if (pendingFocusIndexRef.current !== null) {
      swatchRefs.current[pendingFocusIndexRef.current]?.focus();
      pendingFocusIndexRef.current = null;
    }
  }, [page]);

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (swatchVariants.length === 0) return;

    // Navigate from the actually-focused swatch, not the selected one. When the user
    // chevron-navigates to a different page from the selected colour's page, the focused
    // swatch differs from selectedValue — using selectedValue would compute the wrong
    // next position and jump unexpectedly across pages. Fall back to selectedValue when
    // focus is on something that isn't a swatch (shouldn't happen, but guards the cast).
    const focusedValue = (e.target as HTMLElement).closest<HTMLButtonElement>('[role="radio"]')?.dataset.swatchValue;
    const currentIndex = swatchVariants.findIndex((v) => v.value === (focusedValue ?? selectedValue));
    const isForward = e.key === 'ArrowRight' || e.key === 'ArrowDown';
    const isBackward = e.key === 'ArrowLeft' || e.key === 'ArrowUp';
    if (!isForward && !isBackward) return;

    e.preventDefault();

    let nextIndex: number;
    if (currentIndex === -1) {
      // Nothing selected: forward → first, backward → last.
      // Must NOT fall through to modulo maths — with currentIndex === -1,
      // backward would compute (len - 2), landing on the second-to-last swatch.
      nextIndex = isForward ? 0 : swatchVariants.length - 1;
    } else {
      nextIndex = isForward
        ? (currentIndex + 1) % swatchVariants.length
        : (currentIndex - 1 + swatchVariants.length) % swatchVariants.length;
    }

    onSelect(swatchVariants[nextIndex].value);

    const nextPage = Math.floor(nextIndex / PAGE_SIZE);
    const nextIndexOnPage = nextIndex % PAGE_SIZE;

    if (nextPage !== page) {
      // Page change: set pending focus so the useEffect above applies it after re-render.
      setPage(nextPage);
      pendingFocusIndexRef.current = nextIndexOnPage;
    } else {
      swatchRefs.current[nextIndexOnPage]?.focus();
    }
  };

  // Tab stop: the selected swatch if it's on the current page; otherwise the first swatch
  // on the current page, keeping a single tab stop inside the radiogroup at all times.
  const selectedOnCurrentPage = pagedVariants.some((v) => v.value === selectedValue);

  return (
    <chakra.div __css={styles.container} data-testid="pdp-colour-swatches">
      <chakra.div __css={styles.labelRow}>
        {/* caption-strong: caption textStyle + fontWeight medium (no captionStrong key in typography.ts) */}
        <chakra.span __css={styles.label}>
          {intl.formatMessage({ id: 'colour_swatches.label', defaultMessage: 'Colour:' })}
        </chakra.span>
        {labelName && (
          // testid rather than a role: this is a bare span with no semantics of its own,
          // and E2E needs to assert the selected colour's name independently of the swatches.
          <chakra.span __css={styles.selectedName} data-testid="pdp-colour-selected-name">
            {labelName}
          </chakra.span>
        )}
        {showPagination && (
          // Chevron buttons: 24×24px hit area, 16×16px icon — Figma node 40000307-13867.
          <chakra.div
            __css={styles.paginationGroup}
            role="group"
            aria-label={intl.formatMessage({
              id: 'colour_swatches.pagination.group_label',
              defaultMessage: 'Colour swatch pages',
            })}
          >
            <chakra.button
              __css={styles.chevronButton}
              type="button"
              aria-label={intl.formatMessage({
                id: 'colour_swatches.pagination.previous',
                defaultMessage: 'Previous colours',
              })}
              onClick={() => setPage((p) => Math.max(0, p - 1))}
              disabled={page === 0}
            >
              {/* audit-allow: 16px icon size; no zimm token for swatch control dimensions */}
              <ChevronLeftIcon boxSize="16px" />
            </chakra.button>
            <chakra.button
              __css={styles.chevronButton}
              type="button"
              aria-label={intl.formatMessage({ id: 'colour_swatches.pagination.next', defaultMessage: 'Next colours' })}
              onClick={() => setPage((p) => Math.min(pageCount - 1, p + 1))}
              disabled={page === pageCount - 1}
            >
              {/* audit-allow: 16px icon size; no zimm token for swatch control dimensions */}
              <ChevronRightIcon boxSize="16px" />
            </chakra.button>
          </chakra.div>
        )}
      </chakra.div>

      {showSwatches && (
        <chakra.div
          __css={styles.swatchGroup}
          role="radiogroup"
          aria-label={intl.formatMessage({ id: 'colour_swatches.group.label', defaultMessage: 'Colour' })}
          onKeyDown={handleKeyDown}
        >
          {/* All swatches are always in the DOM so screen readers count the full set.
              Off-page swatches are visually hidden with the SR-safe clip technique
              (position:absolute + clip-path) so they remain in the accessibility tree
              but take no visual space. display:none would hide them from SR entirely. */}
          {swatchVariants.map((variant, globalIndex) => {
            const { value, name, imageUrl } = variant;
            const isSelected = value === selectedValue;
            const indexOnPage = globalIndex - page * PAGE_SIZE;
            const isOnCurrentPage = indexOnPage >= 0 && indexOnPage < PAGE_SIZE;
            const isTabStop = isOnCurrentPage && (isSelected || (!selectedOnCurrentPage && indexOnPage === 0));

            return (
              <chakra.button
                key={value}
                __css={isOnCurrentPage ? styles.swatch : undefined}
                style={
                  isOnCurrentPage
                    ? undefined
                    : {
                        position: 'absolute',
                        width: '1px',
                        height: '1px',
                        padding: 0,
                        margin: '-1px',
                        overflow: 'hidden',
                        clipPath: 'inset(50%)',
                        whiteSpace: 'nowrap',
                        border: 0,
                      }
                }
                type="button"
                ref={(el: HTMLButtonElement | null) => {
                  if (isOnCurrentPage) swatchRefs.current[indexOnPage] = el;
                }}
                role="radio"
                aria-checked={isSelected}
                aria-label={name}
                tabIndex={isTabStop ? 0 : -1}
                data-testid={`pdp-colour-swatch-${value}`}
                data-swatch-value={value}
                // Selected swatch paints above siblings — zIndex driven by selection state.
                sx={isOnCurrentPage ? { zIndex: isSelected ? 1 : undefined } : undefined}
                onClick={() => onSelect(value)}
              >
                {/* imageUrl is typed `string` here via OfferedColourVariant, not merely assumed non-null. */}
                <chakra.div __css={styles.swatchImage}>
                  <img
                    src={sizedSwatchUrl(imageUrl)}
                    alt={name}
                    loading="lazy"
                    width={SWATCH_IMAGE_WIDTH}
                    height={SWATCH_IMAGE_HEIGHT}
                    style={{ width: '100%', height: '100%', objectFit: 'cover', display: 'block' }}
                  />
                </chakra.div>
                {isSelected && <chakra.div __css={styles.selectedIndicator} />}
              </chakra.button>
            );
          })}
        </chakra.div>
      )}
    </chakra.div>
  );
};

export type { ColourVariant, ColourSwatchesProps };
export { ColourSwatches };
export default ColourSwatches;

